  // Great-circle interpolation between two lat/lon points (returns n+1 points)
  function greatCircle(lat1,lon1,lat2,lon2,n){
    var f1=lat1*Math.PI/180, l1=lon1*Math.PI/180;
    var f2=lat2*Math.PI/180, l2=lon2*Math.PI/180;
    var x1=Math.cos(f1)*Math.cos(l1), y1=Math.sin(f1), z1=Math.cos(f1)*Math.sin(l1);
    var x2=Math.cos(f2)*Math.cos(l2), y2=Math.sin(f2), z2=Math.cos(f2)*Math.sin(l2);
    var dot=clamp(x1*x2+y1*y2+z1*z2,-1,1);
    var omega=Math.acos(dot);
    var pts=[];
    for(var i=0;i<=n;i++){
      var t=i/n, sinO=Math.sin(omega);
      var a=sinO>0.001?Math.sin((1-t)*omega)/sinO:(1-t);
      var b=sinO>0.001?Math.sin(t*omega)/sinO:t;
      var x=a*x1+b*x2, y=a*y1+b*y2, z=a*z1+b*z2;
      pts.push({lat:Math.asin(clamp(y,-1,1))*180/Math.PI, lon:Math.atan2(z,x)*180/Math.PI});
    }
    return pts;
  }

  // Ordered journey legs connecting the world tour
  var JOURNEYS=[
    {from:'glasgow',to:'modena'},
    {from:'modena',to:'paris'},
    {from:'paris',to:'ireland'},
    {from:'ireland',to:'kenya'},
    {from:'kenya',to:'boss'}
  ];

  function drawGlobe(){
    var w = globeCanvas.width, h = globeCanvas.height;
    var now = performance.now();
    var pulse = 0.5 + 0.5*Math.sin(now*0.0012);   // 0–1, ~5s cycle
    gctx.clearRect(0,0,w,h);

    // sphere base: deep ocean gradient with a lit side
    var grad = gctx.createRadialGradient(globeCX-80, globeCY-95, 20, globeCX, globeCY, globeR*1.05);
    grad.addColorStop(0, '#2e6ab8');
    grad.addColorStop(0.45, '#1a3f82');
    grad.addColorStop(0.8, '#0e2260');
    grad.addColorStop(1, '#080e30');
    gctx.save();
    gctx.beginPath();
    gctx.arc(globeCX, globeCY, globeR, 0, TAU);
    gctx.fillStyle = grad;
    gctx.fill();
    gctx.clip();

    // real coastlines
    gctx.fillStyle = '#4a9a66';
    gctx.strokeStyle = 'rgba(20,60,30,0.4)';
    gctx.lineWidth = 0.7;
    for(var ri=0; ri<WORLD_LAND.length; ri++){
      var clipped = clipRingToHemisphere(WORLD_LAND[ri], globeRot);
      if(!clipped) continue;
      gctx.beginPath();
      for(var k=0;k<clipped.length;k++){
        var s = projectClipped(clipped[k]);
        if(k===0) gctx.moveTo(s.x,s.y); else gctx.lineTo(s.x,s.y);
      }
      gctx.closePath();
      gctx.fill();
      gctx.stroke();
    }

    // directional shading overlay
    var shade = gctx.createRadialGradient(globeCX-90, globeCY-100, 10, globeCX, globeCY, globeR*1.15);
    shade.addColorStop(0, 'rgba(255,255,255,0.20)');
    shade.addColorStop(0.5, 'rgba(255,255,255,0)');
    shade.addColorStop(1, 'rgba(0,0,10,0.40)');
    gctx.fillStyle = shade;
    gctx.beginPath(); gctx.arc(globeCX, globeCY, globeR, 0, TAU); gctx.fill();

    // faint graticule
    gctx.strokeStyle = 'rgba(255,255,255,0.07)';
    gctx.lineWidth = 1;
    for(var lat=-60; lat<=60; lat+=30){
      gctx.beginPath();
      var first = true;
      for(var lon=-180; lon<=180; lon+=6){
        var p = project(lat,lon);
        if(p.z < -0.05){ first = true; continue; }
        if(first){ gctx.moveTo(p.x,p.y); first=false; } else { gctx.lineTo(p.x,p.y); }
      }
      gctx.stroke();
    }
    for(var lon2=0; lon2<360; lon2+=30){
      gctx.beginPath();
      var first2 = true;
      for(var lat2=-90; lat2<=90; lat2+=6){
        var p2 = project(lat2, lon2);
        if(p2.z < -0.05){ first2 = true; continue; }
        if(first2){ gctx.moveTo(p2.x,p2.y); first2=false; } else { gctx.lineTo(p2.x,p2.y); }
      }
      gctx.stroke();
    }

    // ---- journey arcs ----
    var dashOffset = (now * 0.04) % 20; // marching ants speed
    JOURNEYS.forEach(function(j){
      var fromLoc = LOCATIONS.filter(function(l){ return l.id===j.from; })[0];
      var toLoc   = LOCATIONS.filter(function(l){ return l.id===j.to;   })[0];
      if(!fromLoc || !toLoc) return;
      var fromCleared = progress[j.from] && progress[j.from].cleared;
      var toUnlocked  = toLoc.unlocked;
      if(!fromCleared && !toUnlocked) return;
      var pts = greatCircle(fromLoc.lat, fromLoc.lon, toLoc.lat, toLoc.lon, 30);
      gctx.beginPath();
      var started = false;
      for(var pi=0; pi<pts.length; pi++){
        var pp = project(pts[pi].lat, pts[pi].lon);
        if(pp.z < 0.04){ started = false; continue; }
        if(!started){ gctx.moveTo(pp.x, pp.y); started=true; }
        else { gctx.lineTo(pp.x, pp.y); }
      }
      if(fromCleared){
        // solid gold trail — completed leg
        gctx.strokeStyle = 'rgba(255,207,92,0.75)';
        gctx.lineWidth = 2;
        gctx.setLineDash([]);
      } else {
        // animated dashed preview — next leg
        gctx.strokeStyle = 'rgba(180,210,255,0.45)';
        gctx.lineWidth = 1.5;
        gctx.setLineDash([6, 8]);
        gctx.lineDashOffset = -dashOffset;
      }
      gctx.stroke();
      gctx.setLineDash([]);
      gctx.lineDashOffset = 0;
    });

    // ---- location glow spots on globe surface ----
    LOCATIONS.forEach(function(loc){
      if(!loc.unlocked) return;
      var pg = project(loc.lat, loc.lon);
      if(pg.z < 0.1) return;
      var cleared = progress[loc.id] && progress[loc.id].cleared;
      var r = (cleared ? 28 : 20) * pg.z;
      var gw = gctx.createRadialGradient(pg.x, pg.y, 0, pg.x, pg.y, r);
      var col = cleared ? '255,207,92' : '140,200,255';
      var alpha = cleared ? (0.55 + pulse*0.15) : (0.35 + pulse*0.1);
      gw.addColorStop(0, 'rgba('+col+','+alpha+')');
      gw.addColorStop(1, 'rgba('+col+',0)');
      gctx.fillStyle = gw;
      gctx.beginPath(); gctx.arc(pg.x, pg.y, r, 0, TAU); gctx.fill();
    });

    // drifting cloud wisps
    for(var ci=0; ci<CLOUD_SPOTS.length; ci++){
      var cs = CLOUD_SPOTS[ci];
      var cp = project(cs.lat, cs.lon, cloudRot);
      if(cp.z < 0.05) continue;
      var cAlpha = clamp(cp.z*0.45, 0, 0.38);
      var cg = gctx.createRadialGradient(cp.x, cp.y, 0, cp.x, cp.y, cs.r*cp.z);
      cg.addColorStop(0, 'rgba(255,255,255,'+cAlpha+')');
      cg.addColorStop(1, 'rgba(255,255,255,0)');
      gctx.fillStyle = cg;
      gctx.beginPath(); gctx.arc(cp.x, cp.y, cs.r*cp.z, 0, TAU); gctx.fill();
    }

    gctx.restore();

    // ---- atmosphere: multi-layer pulsing glow ----
    // inner blue rim
    var innerA = 0.32 + pulse*0.10;
    var atmoIn = gctx.createRadialGradient(globeCX, globeCY, globeR*0.93, globeCX, globeCY, globeR*1.07);
    atmoIn.addColorStop(0, 'rgba(110,170,255,'+innerA+')');
    atmoIn.addColorStop(1, 'rgba(110,170,255,0)');
    gctx.fillStyle = atmoIn;
    gctx.beginPath(); gctx.arc(globeCX, globeCY, globeR*1.07, 0, TAU); gctx.fill();

    // outer wide haze
    var outerA = 0.22 + pulse*0.06;
    var atmoOut = gctx.createRadialGradient(globeCX, globeCY, globeR*0.98, globeCX, globeCY, globeR*1.28);
    atmoOut.addColorStop(0, 'rgba(90,150,240,'+outerA+')');
    atmoOut.addColorStop(0.55, 'rgba(70,110,200,0.08)');
    atmoOut.addColorStop(1, 'rgba(60,90,180,0)');
    gctx.fillStyle = atmoOut;
    gctx.beginPath(); gctx.arc(globeCX, globeCY, globeR*1.28, 0, TAU); gctx.fill();

    // bright rim stroke
    gctx.beginPath();
    gctx.arc(globeCX, globeCY, globeR, 0, TAU);
    gctx.lineWidth = 2;
    gctx.strokeStyle = 'rgba(190,225,255,'+(0.45+pulse*0.18)+')';
    gctx.stroke();
  }

  var pinEls = {}, chipEls = {};
  var rosterEl = document.getElementById('roster');
  LOCATIONS.forEach(function(loc){
    var btn = document.createElement('button');
    btn.className = 'pin' + (loc.unlocked ? '' : ' locked');
    btn.setAttribute('aria-label', loc.name + (loc.unlocked ? '' : ' (coming soon)'));
    var dot = document.createElement('div'); dot.className = 'dot';
    btn.appendChild(dot);
    if(loc.unlocked){
      btn.addEventListener('click', function(){
        if(netRole==='guest' && netConnected) return; // guest follows the host once paired up
        enterLocation(loc);
      });
    } else {
      btn.disabled = true;
    }
    globeWrap.appendChild(btn);
    pinEls[loc.id] = btn;

    var chip = document.createElement('div');
    chip.className = 'chip' + (loc.unlocked ? ' active' : '');
    chip.innerHTML = '<span class="dot-mini"></span>' + loc.name;
    chip.title = loc.unlocked ? 'Play ' + loc.name : 'Locked';
    if(loc.unlocked){
      chip.style.cursor = 'pointer';
      (function(l){ chip.addEventListener('click', function(){
        enterLocation(l);
      }); })(loc);
    }
    rosterEl.appendChild(chip);
    chipEls[loc.id] = chip;
  });

  function unlockLocation(id){
    var loc = LOCATIONS.filter(function(l){ return l.id===id; })[0];
    if(!loc || loc.unlocked) return;
    loc.unlocked = true;
    var btn = pinEls[id];
    if(btn){
      btn.classList.remove('locked');
      btn.setAttribute('aria-label', loc.name);
      btn.disabled = false;
      btn.addEventListener('click', function(){
        if(netRole==='guest' && netConnected) return;
        enterLocation(loc);
      });
    }
    var chip = chipEls[id];
    if(chip){
      chip.classList.add('active');
      chip.title = 'Play ' + loc.name;
      chip.style.cursor = 'pointer';
      (function(l){ chip.addEventListener('click', function(){ enterLocation(l); }); })(loc);
    }
    // cinematic: zoom out to see world, rotate to new region, zoom back in
    globeTargetZoom = 0.78;
    setTimeout(function(){
      globeTargetRot = -(loc.lon * Math.PI/180);
      globeTargetZoom = 1.1;
    }, 900);
    setTimeout(function(){ globeTargetZoom = 1.0; }, 2200);
  }

  function refreshClearedPin(){
    // Europe → Africa: unlock Kenya once all 4 European locations are cleared
    var europeDone = ['glasgow','modena','paris','ireland'].every(function(id){
      return progress[id] && progress[id].cleared;
    });
    if(europeDone) unlockLocation('kenya');

    // Ireland → Athens (bonus European level)
    if(progress.ireland && progress.ireland.cleared) unlockLocation('athens');
    // Kenya → Tokyo
    if(progress.kenya && progress.kenya.cleared) unlockLocation('tokyo');
    // Tokyo → Brazil
    if(progress.tokyo && progress.tokyo.cleared) unlockLocation('brazil');
    // Brazil → New York
    if(progress.brazil && progress.brazil.cleared) unlockLocation('newyork');
    // New York → Boss (China)
    if(progress.newyork && progress.newyork.cleared) unlockLocation('boss');

    // Also keep old Africa → Asia path if someone had legacy save
    var africaDone = progress.kenya && progress.kenya.cleared;
    if(africaDone && (!progress.tokyo || !progress.tokyo.cleared) && (!progress.brazil || !progress.brazil.cleared) && (!progress.newyork || !progress.newyork.cleared)) unlockLocation('boss');

    LOCATIONS.forEach(function(loc){
      var pr = progress[loc.id];
      if(pr && pr.cleared && pinEls[loc.id]) pinEls[loc.id].classList.add('cleared');
    });
    renderBestScores();
    buildSkinDots();
  }
  function renderBestScores(){
    var el = document.getElementById('bestScoreLine');
    var parts = [];
    LOCATIONS.forEach(function(loc){
      var pr = progress[loc.id];
      if(pr && pr.best > 0){
        var entry = loc.name + ': ' + pr.best;
        if(pr.name) entry += ' (' + pr.name + ')';
        parts.push(entry);
      }
    });
    if(parts.length){ el.hidden = false; el.textContent = 'Best runs — ' + parts.join('  ·  '); }
    else { el.hidden = true; }
  }
  refreshClearedPin();

  function positionPins(){
    var rect = globeCanvas.getBoundingClientRect();
    var scale = rect.width / globeCanvas.width;
    LOCATIONS.forEach(function(loc){
      var p = project(loc.lat, loc.lon);
      var el = pinEls[loc.id];
      var visible = p.z > -0.15;
      el.style.opacity = visible ? clamp(0.35 + p.z*0.9, 0.25, 1) : 0;
      el.style.pointerEvents = (visible && loc.unlocked) ? 'auto' : 'none';
      var sx = p.x*scale, sy = p.y*scale;
      var sc = clamp(0.7+p.z*0.5,0.6,1.15);
      el.style.transform = 'translate(' + (sx-8*sc) + 'px,' + (sy-8*sc) + 'px) scale(' + sc + ')';
      el.style.zIndex = String(Math.round(1000 + p.z*100));
    });
  }

  var globeRunning = true;
  function globeLoop(t){
    if(globeRunning){
      // smooth zoom
      globeZoom += (globeTargetZoom - globeZoom) * 0.1;
      globeR = GLOBE_BASE_R * globeZoom;
      // smooth rotation toward target (when a chip is clicked)
      if(globeTargetRot !== null){
        var diff = globeTargetRot - globeRot;
        // wrap to shortest arc
        while(diff > Math.PI) diff -= Math.PI*2;
        while(diff < -Math.PI) diff += Math.PI*2;
        globeRot += diff * 0.08;
        if(Math.abs(diff) < 0.005) globeTargetRot = null;
        dragVel = 0;
      } else if(!draggingGlobe){
        globeRot += 0.0014 + dragVel;
        dragVel *= 0.92;
      }
      cloudRot += 0.0024;
      globeCY = 300 + Math.sin(t * 0.00055) * 8;
      drawGlobe();
      positionPins();
    }
    requestAnimationFrame(globeLoop);
  }
  requestAnimationFrame(globeLoop);

  // drag to spin
  globeCanvas.addEventListener('pointerdown', function(e){
    draggingGlobe = true; dragLastX = e.clientX; globeCanvas.setPointerCapture(e.pointerId);
  });
  globeCanvas.addEventListener('pointermove', function(e){
    if(!draggingGlobe) return;
    var dx = e.clientX - dragLastX;
    dragLastX = e.clientX;
    // scale by canvas display ratio so full-swipe = ~180° on any screen size
    var displayW = globeCanvas.getBoundingClientRect().width || 460;
    var sensitivity = Math.PI / displayW;
    globeRot += dx * sensitivity;
    dragVel = dx * sensitivity * 0.1;
    globeTargetRot = null; // cancel any auto-navigate
  });
  ['pointerup','pointercancel','pointerleave'].forEach(function(ev){
    globeCanvas.addEventListener(ev, function(){ draggingGlobe = false; });
  });
  // scroll/pinch zoom
  globeCanvas.addEventListener('wheel', function(e){
    e.preventDefault();
    globeTargetZoom = Math.max(0.8, Math.min(2.5, globeTargetZoom - e.deltaY*0.001));
  }, {passive:false});

  /* =========================================================
     SCENE SWITCHING
  ========================================================= */
  var sceneGlobe = document.getElementById('scene-globe');
  var sceneGame = document.getElementById('scene-game');
  var currentLocationId = 'glasgow';
  var numPlayers = 1;

  function setNumPlayers(n){
    numPlayers = n;
    document.querySelectorAll('.mode-btn').forEach(function(b){
      b.classList.toggle('active', b.dataset.players===String(n));
    });
    document.getElementById('p2Controls').hidden = (n!==2);
  }
  function selectMode(modeStr){
    document.querySelectorAll('.mode-btn').forEach(function(b){
      b.classList.toggle('active', b.dataset.players===modeStr);
    });
    if(modeStr==='net'){
      numPlayers = 2;
      document.getElementById('localControls').hidden = true;
      document.getElementById('localControlsHint').hidden = true;
      document.getElementById('p2Controls').hidden = true;
      document.getElementById('netPanel').hidden = false;
      netUiRefresh();
    } else {
      netTeardown();
      document.getElementById('netPanel').hidden = true;
      document.getElementById('localControls').hidden = false;
      document.getElementById('localControlsHint').hidden = false;
      numPlayers = (modeStr==='2') ? 2 : 1;
      document.getElementById('p2Controls').hidden = (numPlayers!==2);
      document.getElementById('btnStart').hidden = false;
    }
  }
  document.querySelectorAll('.mode-btn').forEach(function(btn){
    btn.addEventListener('click', function(){ selectMode(btn.dataset.players); });
  });

  function enterLocation(loc){
    globeRunning = false;
    sceneGlobe.hidden = true;
    sceneGame.hidden = false;
    currentLocationId = loc.id;
    var cIdx2=-1;
    for(var ci5=0;ci5<CAMPAIGN.length;ci5++){ if(CAMPAIGN[ci5].type==='level'&&CAMPAIGN[ci5].id===loc.id){ cIdx2=ci5; break; } }
    campaignMode = cIdx2>=0; campaignLastType = 'level';
    if(campaignMode){ campaignPlayedLevels = [loc.id]; campaignPlayedMgs = []; }
    if(netRole){
      numPlayers = 2;
      document.getElementById('p2Controls').hidden = true;
    } else {
      selectMode('1');
    }
    var level = LEVELS[loc.id];
    var locPlayCount = (progress[loc.id] && progress[loc.id].playCount) || 0;
    var tier = Math.min(locPlayCount+1, 10);
    document.getElementById('hudLocation').textContent = loc.name + (locPlayCount > 0 ? ' T' + tier : '');
    document.getElementById('howtoTitle').textContent = 'Touch down in ' + loc.name;
    document.getElementById('howtoBlurb').textContent = level.blurb;
    resetGame();
    document.getElementById('howto').hidden = false;
    netUiRefresh();
    netHudRefresh();
    if(netRole==='host'){ netBroadcastScene('enterLocation', {locationId: loc.id}); }
  }
  function backToMap(){
    if(winNextTimer){ clearTimeout(winNextTimer); winNextTimer = null; }
    var wasHost = (netRole==='host');
    adGameplayStop();
    stopGame();
    sceneGame.hidden = true;
    sceneGlobe.hidden = false;
    globeRunning = true;
    refreshClearedPin();
    updateStreak();
    refreshDailyUI();
    document.getElementById('netHudBadge').hidden = true;
    if(wasHost){ netBroadcastScene('map'); }
  }
  document.getElementById('btnBack').addEventListener('click', backToMap);
  document.getElementById('btnHowtoBack').addEventListener('click', function(){ backToMap(); });
  document.getElementById('btnWinMap').addEventListener('click', backToMap);
  document.getElementById('btnLoseMap').addEventListener('click', backToMap);

  document.getElementById('btnLeaderboard').addEventListener('click', function(){
    openLeaderboard(null, LOCATIONS);
  });
  document.getElementById('btnLeaderboardClose').addEventListener('click', function(){
    document.getElementById('overlayLeaderboard').style.display = 'none';
  });

  function togglePause(){
    if(gameState==='playing'){
      gameState='paused';
      document.getElementById('btnPause').textContent='▶ Resume';
      suspendAudio();
    } else if(gameState==='paused'){
      gameState='playing';
      document.getElementById('btnPause').textContent='⏸ Pause';
      resumeAudio();
    }
  }
  document.getElementById('btnPause').addEventListener('click', togglePause);

  function toggleFullscreen(){
    if(!document.fullscreenElement){
      (document.documentElement.requestFullscreen || document.documentElement.webkitRequestFullscreen ||
       document.documentElement.mozRequestFullScreen).call(document.documentElement);
    } else {
      (document.exitFullscreen || document.webkitExitFullscreen || document.mozCancelFullScreen).call(document);
    }
  }
  document.getElementById('btnFullscreen').addEventListener('click', toggleFullscreen);
  document.getElementById('btnFullscreenGlobe').addEventListener('click', toggleFullscreen);
  document.addEventListener('fullscreenchange', function(){
    var fs = !!document.fullscreenElement;
    document.getElementById('btnFullscreen').textContent = fs ? '✕' : '⛶';
    document.getElementById('btnFullscreenGlobe').textContent = fs ? '✕' : '⛶';
  });
  document.getElementById('volSlider').addEventListener('input', function(){
    var v = parseFloat(this.value);
    setMasterVolume(muted ? 0 : v);
    if(bgmAudio) bgmAudio.volume = muted ? 0 : Math.min(1, v * 0.6);
    safeSet('gh_volume_v1', {vol:v, muted:muted});
  });
  var muted = false;
  setMutedGetter(function(){ return muted; });
  setMusicMutedGetter(function(){ return muted; });
  document.getElementById('btnMute').addEventListener('click', function(){
    muted = !muted;
    var v = parseFloat(document.getElementById('volSlider').value);
    setMasterVolume(muted ? 0 : v);
    if(bgmAudio) bgmAudio.volume = muted ? 0 : Math.min(1, v * 0.6);
    this.textContent = muted ? '🔇' : '🔊';
    safeSet('gh_volume_v1', {vol:v, muted:muted});
  });
  // Load saved volume on startup
  (function(){
    var savedVol = safeGet('gh_volume_v1', {vol:0.5, muted:false});
    var slider = document.getElementById('volSlider');
    var muteBtn = document.getElementById('btnMute');
    if(slider) slider.value = savedVol.vol;
    if(savedVol.muted){ muted = true; if(muteBtn) muteBtn.textContent = '🔇'; }
  })();

  /* =========================================================
     ONLINE MULTIPLAYER (two separate phones)
     Serverless WebRTC via Trystero, connected through public
     relays -- no account or server of ours required. This only
     works once the page is served over the open internet (it
     cannot reach out to the network from inside this in-chat
     preview), and it needs both players to have an internet
     connection. The host's device simulates the whole level;
     the guest's device just sends button presses and shows
     whatever the host sends back.
  ========================================================= */
  var NET_APP_ID = 'globehopper-jack-gift-v1';
  var NET_IMPORT_URL = 'https://esm.run/trystero';
  var netJoinRoomFn = null;
  var netRole = null;        // null | 'host' | 'guest'
  var netRoomCode = '';
  var netRoom = null;
  var netActions = null;
  var netConnected = false;
  var netPeerId = null;
  var netLastSentInput = null;
  var netStateAccum = 0;

  function netRandCode(){
    var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    var s = '';
    for(var i=0;i<5;i++) s += chars[Math.floor(Math.random()*chars.length)];
    return s;
  }

  function netSetStatus(msg, cls){
    var el = document.getElementById('netStatus');
    if(!el) return;
    el.textContent = msg;
    el.className = 'net-status' + (cls ? (' '+cls) : '');
  }

  function netUiRefresh(){
    var netPanel = document.getElementById('netPanel');
    if(!netPanel || netPanel.hidden) return;
    var chooseEl = document.getElementById('netChooseRole');
    var codeEl = document.getElementById('netCodeDisplay');
    var introHint = document.getElementById('netIntroHint');
    var controlsHint = document.getElementById('netControlsHint');
    var startBtn = document.getElementById('btnStart');

    if(!netRole){
      chooseEl.hidden = false;
      codeEl.hidden = true;
      introHint.hidden = false;
      controlsHint.hidden = true;
      netSetStatus('');
      startBtn.hidden = true;
      return;
    }
    chooseEl.hidden = true;
    introHint.hidden = true;
    controlsHint.hidden = false;
    if(netRole==='host'){
      codeEl.hidden = false;
      codeEl.textContent = netRoomCode;
      if(netConnected){
        netSetStatus('Connected with your friend! Press Start when you’re both ready.', 'ok');
        startBtn.hidden = false;
      } else {
        netSetStatus('Share this code with your friend — waiting for them to join…', '');
        startBtn.hidden = true;
      }
    } else {
      codeEl.hidden = true;
      if(netConnected){
        netSetStatus('Connected! Waiting for the host to press Start…', 'ok');
      } else {
        netSetStatus('Connecting…', '');
      }
      startBtn.hidden = true;
    }
  }

  function netHudRefresh(){
    var badge = document.getElementById('netHudBadge');
    var text = document.getElementById('netHudBadgeText');
    if(!badge) return;
    if(!netRole || sceneGame.hidden){ badge.hidden = true; return; }
    badge.hidden = false;
    badge.classList.toggle('lost', !netConnected);
    text.textContent = netConnected ? 'Online · connected' : 'Online · waiting…';
  }

  async function netLoadJoinRoom(){
    if(netJoinRoomFn) return netJoinRoomFn;
    var mod = await import(NET_IMPORT_URL);
    netJoinRoomFn = mod.joinRoom;
    return netJoinRoomFn;
  }

  function netSetupRoomHandlers(){
    var actions = {
      input: netRoom.makeAction('input'),
      press: netRoom.makeAction('press'),
      state: netRoom.makeAction('state'),
      scene: netRoom.makeAction('scene')
    };
    netActions = actions;

    netRoom.onPeerJoin = function(peerId){
      netPeerId = peerId;
      netConnected = true;
      netUiRefresh();
      netHudRefresh();
      if(netRole==='host'){
        netActions.scene.send({type:'enterLocation', locationId: currentLocationId});
      }
    };
    netRoom.onPeerLeave = function(){
      netConnected = false;
      netPeerId = null;
      netUiRefresh();
      netHudRefresh();
      netSetStatus('Your friend disconnected.', 'warn');
    };

    if(netRole==='host'){
      actions.input.onMessage = function(data){
        if(!data) return;
        keys.p2Left = !!data.left;
        keys.p2Right = !!data.right;
        keys.p2Jump = !!data.jump;
        keys.p2Bubble = !!data.bubble;
      };
      actions.press.onMessage = function(data){
        if(!players || players.length<2) return;
        if(data==='jump') tryJump(players[1]);
        else if(data==='bubble') tryShoot(players[1]);
      };
    } else {
      actions.state.onMessage = function(data){ applyRemoteState(data); };
      actions.scene.onMessage = function(data){ applyRemoteScene(data); };
    }
  }

  async function netHostStart(){
    netRole = 'host';
    netRoomCode = netRandCode();
    netConnected = false;
    netUiRefresh();
    try{
      var joinRoom = await netLoadJoinRoom();
      netRoom = joinRoom({appId: NET_APP_ID}, 'gh-' + netRoomCode);
      netSetupRoomHandlers();
    }catch(err){
      netSetStatus('Couldn’t start online play here — this only works once the game is hosted on the open web, not from this in-chat preview.', 'warn');
      console.error('netHostStart failed', err);
    }
  }

  async function netJoinStart(code){
    netRole = 'guest';
    netRoomCode = code;
    netConnected = false;
    netUiRefresh();
    try{
      var joinRoom = await netLoadJoinRoom();
      netRoom = joinRoom({appId: NET_APP_ID}, 'gh-' + code);
      netSetupRoomHandlers();
    }catch(err){
      netSetStatus('Couldn’t connect here — this only works once the game is hosted on the open web, not from this in-chat preview.', 'warn');
      console.error('netJoinStart failed', err);
    }
  }

  function netTeardown(){
    if(netRoom){ try{ netRoom.leave(); }catch(e){} }
    netRoom = null;
    netActions = null;
    netRole = null;
    netConnected = false;
    netPeerId = null;
    netRoomCode = '';
    netLastSentInput = null;
    var badge = document.getElementById('netHudBadge');
    if(badge) badge.hidden = true;
    var winRow = document.getElementById('winBtnRow'); if(winRow) winRow.hidden = false;
    var winWait = document.getElementById('winWaitHint'); if(winWait) winWait.hidden = true;
    var loseRow = document.getElementById('loseBtnRow'); if(loseRow) loseRow.hidden = false;
    var loseWait = document.getElementById('loseWaitHint'); if(loseWait) loseWait.hidden = true;
  }

  function netBroadcastScene(type, extra){
    if(netRole==='host' && netConnected && netActions){
      var msg = Object.assign({type:type}, extra||{});
      netActions.scene.send(msg);
    }
  }

  function netBroadcastState(){
    if(!(netRole==='host' && netConnected && netActions)) return;
    netActions.state.send({
      gameState: gameState,
      score: score,
      lives: lives,
      enemiesLeft: enemiesLeft,
      currentLocationId: currentLocationId,
      players: players.map(function(p){ return {id:p.id, x:p.x, y:p.y, facing:p.facing, walkPhase:p.walkPhase, invuln:p.invuln}; }),
      enemies: enemies,
      bubbles: bubbles,
      collectibles: collectibles,
      popups: popups,
      winTitle: gameState==='won' ? document.getElementById('winTitle').textContent : null,
      winStars: gameState==='won' ? document.getElementById('winStars').textContent : null,
      winSummary: gameState==='won' ? document.getElementById('winSummary').textContent : null,
      loseSummary: gameState==='lost' ? document.getElementById('loseSummary').textContent : null
    });
  }

  function netSendPress(kind){
    if(netRole==='guest' && netConnected && netActions){
      netActions.press.send(kind);
    }
  }

  function netSendInputIfChanged(){
    if(!(netRole==='guest' && netConnected && netActions)) return;
    var cur = { left: !!keys.p1Left, right: !!keys.p1Right, jump: !!keys.p1Jump, bubble: !!keys.p1Bubble };
    var last = netLastSentInput;
    if(!last || last.left!==cur.left || last.right!==cur.right || last.jump!==cur.jump || last.bubble!==cur.bubble){
      netActions.input.send(cur);
      netLastSentInput = cur;
    }
  }

  function applyRemoteState(data){
    if(!data) return;
    gameState = data.gameState;
    score = data.score;
    lives = data.lives;
    enemiesLeft = data.enemiesLeft;
    currentLocationId = data.currentLocationId;
    if(players && players.length===2 && data.players){
      data.players.forEach(function(sp){
        var lp = players[sp.id];
        if(lp){ lp.x=sp.x; lp.y=sp.y; lp.facing=sp.facing; lp.walkPhase=sp.walkPhase; lp.invuln=sp.invuln; }
      });
    }
    enemies = data.enemies || [];
    bubbles = data.bubbles || [];
    collectibles = data.collectibles || [];
    popups = data.popups || [];
    updateHud();
    var winEl = document.getElementById('overlayWin');
    var loseEl = document.getElementById('overlayLose');
    if(gameState==='won'){
      winEl.hidden = false;
      if(data.winTitle) document.getElementById('winTitle').textContent = data.winTitle;
      if(data.winStars) document.getElementById('winStars').textContent = data.winStars;
      if(data.winSummary) document.getElementById('winSummary').textContent = data.winSummary;
      document.getElementById('winBtnRow').hidden = true;
      document.getElementById('winWaitHint').hidden = false;
    } else {
      winEl.hidden = true;
    }
    if(gameState==='lost'){
      loseEl.hidden = false;
      if(data.loseSummary) document.getElementById('loseSummary').textContent = data.loseSummary;
      document.getElementById('loseBtnRow').hidden = true;
      document.getElementById('loseWaitHint').hidden = false;
    } else {
      loseEl.hidden = true;
    }
  }

  function applyRemoteScene(data){
    if(netRole!=='guest' || !data) return;
    if(data.type==='enterLocation'){
      var loc = LOCATIONS.filter(function(l){ return l.id===data.locationId; })[0];
      if(loc) enterLocation(loc);
    } else if(data.type==='start'){
      gameState = 'playing';
      document.getElementById('howto').hidden = true;
    } else if(data.type==='retry' || data.type==='winAgain'){
      document.getElementById('overlayWin').hidden = true;
      document.getElementById('overlayLose').hidden = true;
      gameState = 'playing';
    } else if(data.type==='map'){
      backToMap();
    }
  }

  function localJumpPress(){
    if(netRole==='guest'){ netSendPress('jump'); return; }
    tryJump(players[0]);
  }
  function localBubblePress(){
    if(netRole==='guest'){ netSendPress('bubble'); return; }
    tryShoot(players[0]);
  }

  document.getElementById('netTabHost').addEventListener('click', function(){
    document.getElementById('netTabHost').classList.add('active');
    document.getElementById('netTabJoin').classList.remove('active');
    document.getElementById('netHostPane').hidden = false;
    document.getElementById('netJoinPane').hidden = true;
  });
  document.getElementById('netTabJoin').addEventListener('click', function(){
    document.getElementById('netTabJoin').classList.add('active');
    document.getElementById('netTabHost').classList.remove('active');
    document.getElementById('netJoinPane').hidden = false;
    document.getElementById('netHostPane').hidden = true;
  });
  document.getElementById('btnNetHost').addEventListener('click', function(){ netHostStart(); });
  document.getElementById('btnNetJoin').addEventListener('click', function(){
    var input = document.getElementById('netCodeInput');
    var code = (input.value||'').trim().toUpperCase();
    if(code.length < 3){ netSetStatus('Enter the code your friend sent you.', 'warn'); return; }
    netJoinStart(code);
  });
  document.getElementById('netCodeInput').addEventListener('input', function(e){
    e.target.value = e.target.value.toUpperCase();
  });
  document.getElementById('netCodeInput').addEventListener('keydown', function(e){
    if(e.key==='Enter'){ document.getElementById('btnNetJoin').click(); }
  });

  /* =========================================================
     GAME ENGINE
  ========================================================= */
  initCanvas();
  var cv = document.getElementById('gameCanvas');
  var GRAVITY = 1500;
  cv.addEventListener('click', function(e){ handleMiniGameClick(e.clientX, e.clientY); });
  cv.addEventListener('touchstart', function(e){
    if(miniGameId){ e.preventDefault(); handleMiniGameClick(e.touches[0].clientX, e.touches[0].clientY); }
  }, {passive:false});

  var keys = {};

  window.addEventListener('keydown', function(e){
    var code = e.code, handled = true;
    switch(code){
      case 'KeyA': keys.p1Left = true; break;
      case 'KeyD': keys.p1Right = true; break;
      case 'KeyW': keys.p1Jump = true; localJumpPress(); break;
      case 'ShiftLeft': case 'ShiftRight': keys.p1Bubble = true; localBubblePress(); break;
      case 'Space': keys.p1Jump = true; localJumpPress(); break;
      case 'ArrowLeft': keys.p2Left = true; break;
      case 'ArrowRight': keys.p2Right = true; break;
      case 'ArrowUp': keys.p2Jump = true; tryJump(numPlayers===2 ? players[1] : players[0]); break;
      case 'Slash': keys.p2Bubble = true; tryShoot(numPlayers===2 ? players[1] : players[0]); break;
      case 'Escape': case 'KeyP': togglePause(); break;
      case 'KeyR': if(gameState==='lost' && netRole!=='guest'){ resetGame(); gameState='playing'; startMusic(); } break;
      default: handled = false;
    }
    if(handled && e.cancelable) e.preventDefault();
  }, {passive:false});
  window.addEventListener('keyup', function(e){
    switch(e.code){
      case 'KeyA': keys.p1Left = false; break;
      case 'KeyD': keys.p1Right = false; break;
      case 'KeyW': keys.p1Jump = false; break;
      case 'ShiftLeft': case 'ShiftRight': keys.p1Bubble = false; break;
      case 'Space': keys.p1Jump = false; break;
      case 'ArrowLeft': keys.p2Left = false; break;
      case 'ArrowRight': keys.p2Right = false; break;
      case 'ArrowUp': keys.p2Jump = false; break;
      case 'Slash': keys.p2Bubble = false; break;
    }
  });

  function bindHold(id, prop, onPress){
    var el = document.getElementById(id);
    var press = function(e){ if(e && e.cancelable) e.preventDefault(); keys[prop] = true; if(onPress) onPress(); };
    var release = function(e){ if(e && e.cancelable) e.preventDefault(); keys[prop] = false; };
    // Touch events first (most reliable on Samsung Internet / older Android WebViews),
    // Pointer events as the modern path, and mouse events as a desktop/synthetic-click fallback.
    el.addEventListener('touchstart', press, {passive:false});
    el.addEventListener('touchend', release, {passive:false});
    el.addEventListener('touchcancel', release, {passive:false});
    el.addEventListener('pointerdown', press);
    el.addEventListener('pointerup', release);
    el.addEventListener('pointerleave', release);
    el.addEventListener('pointercancel', release);
    el.addEventListener('mousedown', press);
    el.addEventListener('mouseup', release);
    el.addEventListener('mouseleave', release);
    el.addEventListener('contextmenu', function(e){ e.preventDefault(); });
  }
  // Touch buttons always drive Player 1.
  bindHold('tLeft','p1Left');
  bindHold('tRight','p1Right');
  bindHold('tJump','p1Jump', function(){ localJumpPress(); });
  bindHold('tBubble','p1Bubble', function(){ localBubblePress(); });

  /* ---- Mobile floating controls ---- */
  function bindMC(id, prop, onPress){
    var el = document.getElementById(id);
    if(!el) return;
    var held = false;
    function press(e){ e.preventDefault(); if(held) return; held=true; el.classList.add('held'); keys[prop]=true; haptic(15); if(onPress) onPress(); }
    function release(e){ e.preventDefault(); held=false; el.classList.remove('held'); keys[prop]=false; }
    el.addEventListener('touchstart', press, {passive:false});
    el.addEventListener('touchend',   release, {passive:false});
    el.addEventListener('touchcancel',release, {passive:false});
    el.addEventListener('pointerdown', press);
    el.addEventListener('pointerup',   release);
    el.addEventListener('pointerleave',release);
    el.addEventListener('pointercancel',release);
    el.addEventListener('contextmenu', function(e){ e.preventDefault(); });
  }
  bindMC('mcLeft',   'p1Left');
  bindMC('mcRight',  'p1Right');
  bindMC('mcJump',   'p1Jump',   function(){ localJumpPress(); });
  bindMC('mcBubble', 'p1Bubble', function(){ localBubblePress(); });

  /* Show/hide mobile controls and portrait warning */
  var isTouchDevice = ('ontouchstart' in window || navigator.maxTouchPoints > 0);
  var mcEl = document.getElementById('mobileControls');
  var pwEl = document.getElementById('portraitWarning');

  function updateMobileUI(){
    if(!isTouchDevice){ if(mcEl) mcEl.style.display='none'; return; }
    var portrait = window.innerHeight > window.innerWidth;
    if(pwEl) pwEl.style.display = portrait ? 'flex' : 'none';
    if(mcEl) mcEl.style.display = portrait ? 'none' : 'block';
  }
  updateMobileUI();
  window.addEventListener('resize', updateMobileUI);
  window.addEventListener('orientationchange', function(){ setTimeout(updateMobileUI, 200); });

  /* Canvas swipe up = jump */
  var swipeStartY = 0;
  document.addEventListener('touchstart', function(e){
    swipeStartY = e.touches[0].clientY;
  }, {passive:true});
  document.addEventListener('touchend', function(e){
    if(!isTouchDevice || gameState !== 'playing') return;
    var dy = swipeStartY - e.changedTouches[0].clientY;
    if(dy > 40){ localJumpPress(); keys.p1Jump = true; setTimeout(function(){ keys.p1Jump = false; }, 120); }
  }, {passive:true});

