    ctx.strokeStyle=trapped?'#eedc80':'#b8920a'; ctx.lineWidth=4;
    ctx.beginPath(); ctx.moveTo(-20,14); ctx.lineTo(-20,-6);
    ctx.quadraticCurveTo(0,-20,20,-6); ctx.stroke();
    // Holes (typical parmesan texture)
